from pathlib import Path
p=Path('index.html')
s=p.read_text(encoding='utf-8')
start='<!-- ABSENCE_MODAL_REDESIGN_START -->'
end='<!-- ABSENCE_MODAL_REDESIGN_END -->'
if start in s and end in s:
    a=s.index(start); b=s.index(end)+len(end); s=s[:a]+s[b:]
block=r'''<!-- ABSENCE_MODAL_REDESIGN_START -->
<style>
.abs-modal-backdrop{position:fixed;inset:0;z-index:9999;background:rgba(2,8,15,.78);backdrop-filter:blur(8px);display:grid;place-items:center;padding:22px}
.abs-modal{width:min(760px,96vw);max-height:92vh;overflow:auto;background:linear-gradient(180deg,#0e1b2b,#091522);border:1px solid #294158;border-radius:18px;box-shadow:0 28px 90px rgba(0,0,0,.58)}
.abs-modal-head{display:flex;align-items:flex-start;justify-content:space-between;padding:22px 24px 18px;border-bottom:1px solid #20344a}.abs-modal-head .eyebrow{margin-bottom:5px}.abs-modal-head h2{font-size:22px;margin:0}.abs-modal-head p{color:var(--muted);margin:5px 0 0;font-size:12px}.abs-modal-close{border:1px solid #2b4057;background:#101e2e;color:#9fb2c7;width:36px;height:36px;border-radius:9px;font-size:16px}
.abs-modal-body{padding:22px 24px}.abs-field{display:flex;flex-direction:column;gap:7px;margin-bottom:18px}.abs-field>label,.abs-field-label{font-size:11px;color:#9db0c5;font-weight:800;letter-spacing:.04em}.abs-input,.abs-select,.abs-textarea{width:100%;background:#0a1725;border:1px solid #294159;color:#eef7ff;border-radius:10px;padding:11px 12px;outline:none}.abs-input:focus,.abs-select:focus,.abs-textarea:focus{border-color:#2ed9b8;box-shadow:0 0 0 3px rgba(46,217,184,.1)}
.abs-types{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.abs-type-card{border:1px solid #294159;background:#0c1928;color:#a9bdd2;border-radius:11px;padding:12px 9px;text-align:center;transition:.15s}.abs-type-card:hover{border-color:#3a5a76;background:#102235}.abs-type-card.active{border-color:#2ed9b8;background:#12332e;color:#e9fff9;box-shadow:0 0 0 2px rgba(46,217,184,.13)}.abs-type-card span{display:block;font-size:18px;margin-bottom:5px}.abs-type-card b{font-size:11px}
.abs-grid-2{display:grid;grid-template-columns:1fr 1fr;gap:12px}.abs-toggle-row{display:flex;align-items:center;justify-content:space-between;border:1px solid #294159;background:#0b1826;border-radius:11px;padding:12px 14px;margin-bottom:18px}.abs-toggle-copy b{font-size:12px}.abs-toggle-copy small{display:block;color:var(--muted);margin-top:3px}.abs-switch{position:relative;width:46px;height:25px}.abs-switch input{display:none}.abs-switch i{position:absolute;inset:0;background:#263a50;border-radius:99px;transition:.2s}.abs-switch i:after{content:'';position:absolute;width:19px;height:19px;left:3px;top:3px;background:#dbe6f2;border-radius:50%;transition:.2s}.abs-switch input:checked+i{background:#25cfae}.abs-switch input:checked+i:after{transform:translateX(21px);background:#052a23}
.abs-time-fields{display:none;margin-top:-6px;margin-bottom:18px}.abs-time-fields.show{display:grid}.abs-conflict-box{border:1px solid #284d42;background:#0e2a24;border-radius:11px;padding:12px 14px;color:#9be5cf;font-size:12px;margin-top:4px}.abs-conflict-box.warn{border-color:#765126;background:#302313;color:#ffd08a}.abs-conflict-item{margin-top:6px;padding-top:6px;border-top:1px solid rgba(255,255,255,.08)}
.abs-modal-foot{display:flex;justify-content:flex-end;gap:9px;padding:18px 24px;border-top:1px solid #20344a;background:#0a1623;position:sticky;bottom:0}.abs-modal-foot .primary{min-width:180px}
@media(max-width:700px){.abs-types{grid-template-columns:repeat(2,1fr)}.abs-grid-2{grid-template-columns:1fr}.abs-modal-backdrop{padding:8px}.abs-modal-body{padding:18px}.abs-modal-head{padding:18px}.abs-modal-foot{padding:14px 18px}}
</style>
<script>
let absenceModalType='Urlaub';
function absenceTypeIcon(t){return({Urlaub:'☀',Krank:'✚',Frei:'◷',Fortbildung:'◆',Sperrzeit:'⊘',Sonderurlaub:'★',Sonstiges:'…'})[t]||'•'}
function setAbsenceModalType(t){absenceModalType=t;document.querySelectorAll('.abs-type-card').forEach(b=>b.classList.toggle('active',b.dataset.type===t));updateAbsenceModalConflicts()}
function toggleAbsenceTimeFields(){const full=document.getElementById('absFullDay')?.checked;document.getElementById('absTimeFields')?.classList.toggle('show',!full);updateAbsenceModalConflicts()}
function absenceModalDates(){const st=document.getElementById('absStart')?.value,en=document.getElementById('absEnd')?.value||st;if(!st||!en||en<st)return[];let d=new Date(st+'T00:00:00'),e=new Date(en+'T00:00:00'),out=[];while(d<=e){out.push(iso(d));d=addDays(d,1)}return out}
function updateAbsenceModalConflicts(){const box=document.getElementById('absLiveConflict');if(!box)return;const empId=document.getElementById('absEmp')?.value,dates=absenceModalDates();if(!empId||!dates.length){box.className='abs-conflict-box';box.innerHTML='✓ Zeitraum auswählen, um den Dienstplan automatisch zu prüfen.';return}const hits=assignments.filter(a=>a.employeeId===empId&&dates.includes(a.date));if(!hits.length){box.className='abs-conflict-box';box.innerHTML='✓ Keine Dienstplankonflikte im gewählten Zeitraum.';return}const emp=employees.find(e=>e.id===empId);box.className='abs-conflict-box warn';box.innerHTML=`⚠ <b>${hits.length} Dienstplan-Konflikt${hits.length===1?'':'e'} erkannt</b>${hits.map(h=>`<div class="abs-conflict-item">${new Date(h.date+'T00:00:00').toLocaleDateString('de-DE',{weekday:'short',day:'2-digit',month:'2-digit'})} · ${h.type} · ${emp?.first||''} ${emp?.last||''}</div>`).join('')}`}
function openAbsenceDialog(id=null){absenceEditingId=id;const a=id?absences.find(x=>x.id===id):null;absenceModalType=a?.type||'Urlaub';document.getElementById('absenceModal')?.remove();const active=employees.filter(e=>e.status==='active'||e.id===a?.employeeId);const empOptions=active.map(e=>`<option value="${e.id}" ${a?.employeeId===e.id?'selected':''}>${e.first} ${e.last}${e.personnelNo?' · '+e.personnelNo:''}</option>`).join('');const types=['Urlaub','Krank','Frei','Fortbildung','Sperrzeit','Sonderurlaub','Sonstiges'];const currentStatus=typeof absenceStatus==='function'?absenceStatus(a||{}):(a?.status||'Genehmigt');const start=a?.startDate||a?.date||iso(new Date()),end=a?.endDate||a?.date||start;const full=a?.fullDay!==false;const html=`<div class="abs-modal-backdrop" id="absenceModal" onclick="if(event.target===this)this.remove()"><div class="abs-modal" role="dialog" aria-modal="true" aria-labelledby="absenceModalTitle"><div class="abs-modal-head"><div><div class="eyebrow">ABWESENHEIT</div><h2 id="absenceModalTitle">${a?'Abwesenheit bearbeiten':'Abwesenheit beantragen'}</h2><p>Zeitraum erfassen und mögliche Dienstplankonflikte direkt prüfen.</p></div><button class="abs-modal-close" onclick="document.getElementById('absenceModal').remove()">✕</button></div><div class="abs-modal-body"><div class="abs-field"><label>Mitarbeiter</label><select class="abs-select" id="absEmp" onchange="updateAbsenceModalConflicts()">${empOptions}</select></div><div class="abs-field"><div class="abs-field-label">Abwesenheitsart</div><div class="abs-types">${types.map(t=>`<button type="button" class="abs-type-card ${absenceModalType===t?'active':''}" data-type="${t}" onclick="setAbsenceModalType('${t}')"><span>${absenceTypeIcon(t)}</span><b>${t}</b></button>`).join('')}</div></div><div class="abs-grid-2"><div class="abs-field"><label>Von</label><input class="abs-input" id="absStart" type="date" value="${start}" onchange="if(document.getElementById('absEnd').value<this.value)document.getElementById('absEnd').value=this.value;updateAbsenceModalConflicts()"></div><div class="abs-field"><label>Bis</label><input class="abs-input" id="absEnd" type="date" value="${end}" onchange="updateAbsenceModalConflicts()"></div></div><div class="abs-toggle-row"><div class="abs-toggle-copy"><b>Ganztägige Abwesenheit</b><small>Deaktivieren, wenn nur ein Teil des Tages betroffen ist.</small></div><label class="abs-switch"><input id="absFullDay" type="checkbox" ${full?'checked':''} onchange="toggleAbsenceTimeFields()"><i></i></label></div><div class="abs-grid-2 abs-time-fields ${full?'':'show'}" id="absTimeFields"><div class="abs-field"><label>Von Uhrzeit</label><input class="abs-input" id="absStartTime" type="time" value="${a?.startTime||''}"></div><div class="abs-field"><label>Bis Uhrzeit</label><input class="abs-input" id="absEndTime" type="time" value="${a?.endTime||''}"></div></div><div class="abs-grid-2"><div class="abs-field"><label>Status</label><select class="abs-select" id="absStatus"><option ${currentStatus==='Beantragt'?'selected':''}>Beantragt</option><option ${currentStatus==='Genehmigt'?'selected':''}>Genehmigt</option><option ${currentStatus==='Erfasst'?'selected':''}>Erfasst</option><option ${currentStatus==='Abgelehnt'?'selected':''}>Abgelehnt</option></select></div><div class="abs-field"><label>Kurzhinweis <span style="color:#627b94;font-weight:400">optional</span></label><input class="abs-input" id="absTime" value="${a?.timeNote||''}" placeholder="z. B. Arzttermin"></div></div><div class="abs-field"><label>Bemerkung <span style="color:#627b94;font-weight:400">optional</span></label><textarea class="abs-textarea" id="absNote" rows="3" placeholder="Interne Notiz zur Abwesenheit ...">${a?.note||''}</textarea></div><div id="absLiveConflict" class="abs-conflict-box"></div></div><div class="abs-modal-foot"><button class="ghost" onclick="document.getElementById('absenceModal').remove()">Abbrechen</button><button class="primary" onclick="saveAbsenceDialog()">${a?'Änderungen speichern':'Abwesenheit speichern'}</button></div></div></div>`;document.body.insertAdjacentHTML('beforeend',html);updateAbsenceModalConflicts()}
function saveAbsenceDialog(){const start=document.getElementById('absStart')?.value,end=document.getElementById('absEnd')?.value;if(!start||!end||end<start){alert('Bitte einen gültigen Zeitraum wählen.');return}const full=document.getElementById('absFullDay')?.checked!==false;const data={employeeId:document.getElementById('absEmp').value,startDate:start,endDate:end,date:start,type:absenceModalType,status:document.getElementById('absStatus').value,fullDay:full,startTime:full?'':(document.getElementById('absStartTime')?.value||''),endTime:full?'':(document.getElementById('absEndTime')?.value||''),timeNote:document.getElementById('absTime')?.value.trim()||'',note:document.getElementById('absNote')?.value.trim()||''};if(absenceEditingId){const row=absences.find(x=>x.id===absenceEditingId);if(row)Object.assign(row,data)}else absences.push({id:'a'+Date.now(),...data});saveAll();document.getElementById('absenceModal')?.remove();if(typeof renderAbsenceDashboard==='function')renderAbsenceDashboard();if(typeof renderCalendar==='function')renderCalendar();if(typeof renderOverview==='function')renderOverview();showSaveToast('Abwesenheit gespeichert','Zeitraum, Art und Status wurden erfolgreich übernommen.')}
</script>
<!-- ABSENCE_MODAL_REDESIGN_END -->'''
s=s.replace('</body>',block+'\n</body>')
p.write_text(s,encoding='utf-8')
print('absence modal redesign applied')
